151: // ---------- state + serialized saves ----------
152: 
153: function createRepository(filePath, initialStore) {
154:   let store = initialStore;
155:   let queue = Promise.resolve();
156: 
157:   /** Runs `change(store)` -> next store (or an HttpError), saves it, then commits it. One at a time. */
158:   function mutate(change) {
159:     const run = queue.then(async () => {
160:       const next = freezeStore(change(store));
161:       await writeFile(filePath, JSON.stringify(next));
162:       store = next;
163:       return next;
164:     });
165:     queue = run.catch(() => undefined); // keep the chain alive; the caller handles `run`'s rejection
166:     return run;
167:   }
168: 
169:   return { current: () => store, mutate };
170: }
