174: function sendJson(res, status, payload) {
175:   const body = Buffer.from(JSON.stringify(payload), 'utf8');
176:   res.writeHead(status, { 'Content-Type': JSON_TYPE, 'Content-Length': body.length });
177:   res.end(body);
178: }
179: 
180: function sendError(res, status, message) {
181:   sendJson(res, status, { error: message });
182: }
