255: // ---------- routing ----------
256: 
257: function splitTarget(target) {
258:   const at = target.indexOf('?');
259:   return at === -1 ? { pathname: target, query: '' } : { pathname: target.slice(0, at), query: target.slice(at + 1) };
260: }
261: 
262: /** Maps a raw path to a route name and parameter; null when no route matches. */
263: function matchRoute(pathname) {
264:   if (pathname === '/api/rooms') return { name: 'rooms', methods: ['GET'] };
265:   if (pathname === '/api/bookings') return { name: 'bookings', methods: ['GET', 'POST'] };
266:   if (Object.hasOwn(STATIC_FILES, pathname)) return { name: 'static', methods: ['GET'] };
267:   if (pathname.startsWith(BOOKINGS_PREFIX)) {
268:     const id = pathname.slice(BOOKINGS_PREFIX.length);
269:     if (id !== '' && !id.includes('/')) return { name: 'booking', methods: ['DELETE'], id };
270:   }
271:   return null;
272: }
273: 
274: async function dispatch(repo, req, res, body) {
275:   const { pathname, query } = splitTarget(req.url);
276:   const route = matchRoute(pathname);
277:   if (route === null) throw new HttpError(404, MSG.notFound);
278:   if (!route.methods.includes(req.method)) throw new HttpError(405, MSG.method);
279:   if (route.name === 'rooms') return sendJson(res, 200, { rooms: ROOMS });
280:   if (route.name === 'static') return serveStatic(res, STATIC_FILES[pathname]);
281:   if (route.name === 'booking') {
282:     await deleteBooking(repo, route.id);
283:     res.writeHead(204);
284:     return res.end();
285:   }
286:   if (req.method === 'GET') return sendJson(res, 200, { bookings: listBookings(repo, query) });
287:   return sendJson(res, 201, await createBooking(repo, req, body));
288: }
289: 
290: function createHandler(repo) {
291:   return async function handleRequest(req, res) {
292:     try {
293:       const body = await readBody(req, MAX_BODY_BYTES);
294:       await dispatch(repo, req, res, body);
295:     } catch (err) {
296:       replyWithError(res, err);
297:     }
298:   };
299: }
300: 
301: function replyWithError(res, err) {
302:   try {
303:     if (res.headersSent) return res.destroy();
304:     if (err instanceof HttpError) return sendError(res, err.status, err.message);
305:     return sendError(res, 500, MSG.internal);
306:   } catch {
307:     return res.destroy(); // the reply itself failed; drop the connection rather than crash
308:   }
309: }
310: 
311: /** CONNECT bypasses the request handler; answer it on the raw socket (no route allows it). */
312: function handleConnect(req, socket) {
313:   const route = matchRoute(splitTarget(req.url).pathname);
314:   const [status, reason, message] = route === null
315:     ? [404, 'Not Found', MSG.notFound]
316:     : [405, 'Method Not Allowed', MSG.method];
317:   const body = Buffer.from(JSON.stringify({ error: message }), 'utf8');
318:   const head = `HTTP/1.1 ${status} ${reason}\r\nContent-Type: ${JSON_TYPE}\r\n`
319:     + `Content-Length: ${body.length}\r\nConnection: close\r\n\r\n`;
320:   socket.on('error', () => socket.destroy()); // client went away; nothing left to answer
321:   socket.end(Buffer.concat([Buffer.from(head, 'latin1'), body]));
322: }
323: 
324: // ---------- startup ----------
325: 
326: function fail(line) {
327:   process.stderr.write(`${line}\n`);
328:   process.exit(1);
329: }
330: 
331: function parsePort(raw) {
332:   if (raw === undefined || raw === '') return DEFAULT_PORT;
333:   if (!/^[0-9]+$/.test(raw)) return null;
334:   const port = Number(raw);
335:   return port <= 65535 ? port : null;
336: }
337: 
338: function start() {
339:   const port = parsePort(process.env.PORT);
340:   if (port === null) fail(`invalid PORT ${JSON.stringify(process.env.PORT)}`);
341: 
342:   const dataName = process.env.DATA_FILE ? process.env.DATA_FILE : DEFAULT_DATA_FILE;
343:   const dataPath = path.resolve(process.cwd(), dataName);
344:   const store = loadStore(dataPath);
345:   if (store === null) fail(`cannot read data file ${dataName}`);
346: 
347:   const repo = createRepository(dataPath, store);
348:   const handler = createHandler(repo);
349:   const server = http.createServer({ requireHostHeader: false }, handler);
350:   server.on('checkExpectation', handler);
351:   server.on('connect', handleConnect);
352:   let listening = false;
353:   server.on('error', (err) => {
354:     if (!listening) fail(`cannot listen on port ${port}: ${err.code || 'error'}`);
355:     process.stderr.write(`server error: ${err.code || 'error'}\n`);
356:   });
357:   server.listen(port, HOST, () => {
358:     listening = true;
359:     process.stdout.write(`listening on http://${HOST}:${server.address().port}\n`);
360:   });
361: }
