import fs from 'node:fs';
import vm from 'node:vm';
import http from 'node:http';
import { Duplex } from 'node:stream';
import path from 'node:path';
const source = fs.readFileSync('B/server.mjs', 'utf8').replace(/"'^import .*;'"\\r?\\n/gm, '');
function boot(initial = null) {
  const runtime = { disk: initial, writes: 0, failSave: false, handler: null, server: null, stdout: '' };
  const io = {
    readFileSync() { if (runtime.disk === null) throw Object.assign(new Error('missing'), {code:'ENOENT'}); return runtime.disk; },
    writeFileSync(file, text) { runtime.writes++; runtime.disk = runtime.failSave ? text.slice(0, 7) : text; if(runtime.failSave) throw Object.assign(new Error('partial write'),{code:'EIO'}); }
  };
  const proc = { env: {PORT:'0', DATA_FILE:'scratch/memory.json'}, cwd:()=>process.cwd(), stdout:{write:s=>runtime.stdout+=s}, stderr:{write:s=>runtime.stderr=s}, exit:code=>{throw new Error('exit '+code)} };
  const httpMock = {createServer(handler) { runtime.handler=handler; const server=http.createServer(handler); runtime.server=server; server.listen=(port,host,cb)=>{server.address=()=>({port:12345}); cb();}; return server; }};
  vm.runInNewContext(source,{ http:httpMock, fs:io, path, process:proc, Buffer, URLSearchParams },{filename:'B/server.mjs'});
  return runtime;
}
async function send(runtime, method, target, body, headers={'content-type':'application/json'}) {
  const {EventEmitter}=await import('node:events');
  const req=Object.assign(new EventEmitter(),{method,url:target,headers});
  return await new Promise((resolve,reject)=>{
    const res={headersSent:false,destroyed:false,writeHead(status,headers){this.status=status;this.headers=headers;this.headersSent=true;},end(body=''){resolve({status:this.status,body:body?JSON.parse(String(body)):null});}};
    runtime.handler(req,res);
    queueMicrotask(()=>{if(body"'!==undefined) req.emit('"'data',Buffer.isBuffer(body)?body:Buffer.from(typeof body==='string'?body:JSON.stringify(body)));req.emit('end');});
  });
}
const runtime=boot();
const booking={room:'Aurora',title:'  Standup  ',date:'2026-11-03',start:'09:00',end:'10:00'};
const checks=[];
const assert=(name,condition)=>{checks.push({name,pass:Boolean(condition)});if("'!condition)throw new Error(name)};
assert('"'startup output',runtime.stdout==='listening on http://127.0.0.1:12345\\n');
assert('rooms',(await send(runtime,'GET','/api/rooms')).status===200);
