assert('trim and id',made.status===201&&made.body.id===1&&made.body.title==='Standup');
const parallel=await Promise.all(Array.from({length:12},()=>send(runtime,'POST','/api/bookings',{...booking,start:'14:00',end:'15:00'})));
assert('concurrency',parallel.filter(r=>r.status===201).length===1&&parallel.filter(r=>r.status===409).length===11);
assert('restart',(await send(boot(runtime.disk),'GET','/api/bookings')).body.bookings.length===2);
const prior=runtime.disk;
